SELECT manual_id, period, employee_id, employee_name, manual_amount, manual_reason, perf_status, approver,
       approve_time, approve_opinion, del_flag, create_by, create_time, remark
FROM biz_hr_perf_manual
 del_flag = '0'
     AND period = #{period}
     AND employee_id = #{employeeId}
     AND employee_name LIKE CONCAT('%', #{employeeName}, '%')
     AND perf_status = #{perfStatus}

ORDER BY create_time DESC

SELECT manual_id, period, employee_id, employee_name, manual_amount, manual_reason, perf_status, approver,
       approve_time, approve_opinion, del_flag, create_by, create_time, remark
FROM biz_hr_perf_manual WHERE manual_id = #{manualId}


 del_flag = '0'
     AND period = #{period}
     AND employee_id = #{employeeId}
     AND employee_name LIKE CONCAT('%', #{employeeName}, '%')

ORDER BY total_amount DESC
